package com.bank.hiding.service;

import com.bank.hiding.model.*;
import java.util.*;

public class ReportService {

    // ═══ BUG: calling static method on instance reference ═══
    public List<String> generateBuggyReport(List<Account> accounts) {
        List<String> report = new ArrayList<>();
        for (Account account : accounts) {
            // INSTANCE: works correctly — polymorphic!
            String desc = account.getDescription();

            // STATIC: ALWAYS returns Account.getPolicy() — BUG!
            String policy = account.getPolicy();  // compile-time → Account.getPolicy()!
            // Developer expects savings policy for SavingsAccount — WRONG!

            report.add(account.getAccountId() + ": " + desc + " | Policy: " + policy);
        }
        return report;
    }

    // ═══ FIX: use instance method for polymorphic behavior ═══
    public List<String> generateCorrectReport(List<Account> accounts) {
        List<String> report = new ArrayList<>();
        for (Account account : accounts) {
            String desc = account.getDescription();  // INSTANCE — polymorphic (Recommended) 
            // For policy: either make it an instance method, or use class name:
            report.add(account.getAccountId() + ": " + desc);
        }
        return report;
    }
}
