```java
// ─── File: src/test/java/com/bank/hiding/HidingVsOverridingTest.java ───
package com.bank.hiding;

import com.bank.hiding.model.*;
import com.bank.hiding.service.ReportService;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.List;
import static org.assertj.core.api.Assertions.*;

class HidingVsOverridingTest {

    Account savings = new SavingsAccount("SAV001", new BigDecimal("125000"));
    Account current = new CurrentAccount("CUR001", new BigDecimal("500000"));

    // ═══ OVERRIDING: runtime dispatch — correct! ═══
    @Test
    void overriding_runtimeDispatch() {
        // Variable type: Account. Actual type: SavingsAccount.
        assertThat(savings.getDescription()).isEqualTo("Savings Account (4% interest, min Rs.1000)");
        assertThat(current.getDescription()).isEqualTo("Current Account (overdraft Rs.100K)");
        // JVM dispatches to ACTUAL type at runtime — polymorphism!
    }

    // ═══ HIDING: compile-time binding — NO polymorphism! ═══
    @Test
    void hiding_compileTimeBinding() {
        // Variable type: Account. Static method resolved at COMPILE TIME.
        assertThat(savings.getPolicy()).isEqualTo("Standard Banking Policy");  // Account's!
        assertThat(current.getPolicy()).isEqualTo("Standard Banking Policy");  // Account's!
        // NOT "Savings Policy" or "Current Policy"!
        // Because: ref type = Account → compiler binds to Account.getPolicy()
    }

    @Test
    void hiding_changeReferenceTypeChangesResult() {
        // Through Account reference: Account.getPolicy()
        Account refAccount = new SavingsAccount("SAV001", BigDecimal.ZERO);
        assertThat(refAccount.getPolicy()).isEqualTo("Standard Banking Policy");

        // Through SavingsAccount reference: SavingsAccount.getPolicy()
        SavingsAccount refSavings = new SavingsAccount("SAV001", BigDecimal.ZERO);
        assertThat(refSavings.getPolicy()).isEqualTo("Savings Policy: 4% interest, Rs.1000 minimum");

        // SAME OBJECT would give different results if cast!
        // This proves: static = compile-time binding to REFERENCE TYPE.
    }

    @Test
    void hiding_classNameCallIsClearest() {
        // Best practice: call static via CLASS NAME, not instance:
        assertThat(Account.getPolicy()).isEqualTo("Standard Banking Policy");
        assertThat(SavingsAccount.getPolicy()).isEqualTo("Savings Policy: 4% interest, Rs.1000 minimum");
        assertThat(CurrentAccount.getPolicy()).isEqualTo("Current Policy: zero interest, Rs.100K overdraft");
        // CLEAR — no confusion about which class's method is called.
    }

    // ═══ THE BUG: report service uses static via instance ═══
    @Test
    void buggyReport_allShowStandardPolicy() {
        ReportService service = new ReportService();
        List<String> report = service.generateBuggyReport(List.of(savings, current));

        // ALL show "Standard Banking Policy" — NOT the specific policy!
        assertThat(report.get(0)).contains("Standard Banking Policy");  // should be savings!
        assertThat(report.get(1)).contains("Standard Banking Policy");  // should be current!
        // BUG: developer expected polymorphic dispatch but static doesn't do that.
    }

    // ═══ SUMMARY ═══
    @Test
    void summary() {
        Account ref = new SavingsAccount("SAV001", BigDecimal.ZERO);

        // Instance method (getDescription): RUNTIME dispatch
        // ref is Account, actual is SavingsAccount → SavingsAccount.getDescription()
        assertThat(ref.getDescription()).contains("Savings");

        // Static method (getPolicy): COMPILE-TIME binding
        // ref is Account → Account.getPolicy()
        assertThat(ref.getPolicy()).contains("Standard");

        // SAME reference. DIFFERENT resolution mechanism!
    }
}
```

